public static int Main(string[] args)
    {
        var command = GetExecutableSuffix();
        if (command != string.Empty)
        {
            // if the executable name has a suffix, use it as the command and pass no arguments. 
            // This allows creating symlinks or copies of the executable with names like "BovisWeb-server.exe" to directly invoke the server command.
            args = [command, .. args];
        }
        try
        {
            var rootCommand = Builder.BuildRootCommand(typeof(Program));
            if (rootCommand != null)
            {
                return rootCommand.Invoke(args);
            }
            else
            {
                Console.Error.WriteLine("Cannot build argument parser");
                return 1;
            }

        }
        catch (Exception ex)
        {
            MessageDb.ShowException(ex);
            return 1;
        }
    }



