    /// <summary>
    /// Loads a JSON configuration file into the <see cref="ConfigurationManager"/> with verbose logging.
    /// </summary>
    /// <param name="cm">The configuration manager to load into.</param>
    /// <param name="path">Path to the JSON file.</param>
    static void VerboseLoadJson(ConfigurationManager cm, string path)
    {
        if (System.IO.File.Exists(path))
        {
            Console.Error.WriteLine($"BC4C838C148I Loading config file {path}");
            cm.AddJsonFile(path, true);
        }
        else
        {
            Console.Error.WriteLine($"BCE8A6A8210D Config file {path} not found. Ignoring path.");
        }
    }

